export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	common?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	if (input.family === "pi-default") {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	const shared = input.includesFamilyShared ? "" : familySharedBody(input.family, input.root).trim();
	const sharedIncluded = Boolean(shared) && Boolean(rolePrompt) && rolePrompt.includes(shared);
	const files: string[] = [];
	const parts: string[] = [];
	if (shared && !sharedIncluded) parts.push(shared);
	if (rolePrompt) parts.push(rolePrompt);
	if (shared) files.push(`${input.family}/shared.md`);
	if (rolePrompt) files.push("role");
	let text = parts.filter(Boolean).join("\n");
	if (input.common) {
		const common = commonBody(input.root).trim();
		if (common) {
			if (!text.includes(common)) {
				text = text ? `${text}\n${common}` : common;
			}
			files.push("common.md");
		}
	}
	return { family: input.family, text, files };
}

