const FALLBACK_COMMON_BODY = [
	"Think concisely. Keep internal reasoning brief and focused on the immediate step.",
	"Output tool calls directly without conversational filler.",
].join("\n");

export function commonBody(root?: string): string {
	const path = join(root ?? defaultSourcesRoot(), "common.md");
	if (existsSync(path)) return readFileSync(path, "utf8").trim();
	const fallbackPath = join(defaultSourcesRoot(), "common.md");
	if (existsSync(fallbackPath)) return readFileSync(fallbackPath, "utf8").trim();
	return FALLBACK_COMMON_BODY;
}

export function familySharedBody(family: string, root?: string): string {

export function overlayBody(name: HarnessName, root?: string, includeCommon = true): string {
	for (const source of sources(root)) {
		const profile = source.profiles[name];
		if (!profile) continue;
		const parts = [readOptional(source.dir, source.shared), readOptional(source.dir, profile.overlay)];
		if (includeCommon && !String(name).endsWith("-plan")) parts.push(commonBody(root));
		return parts.filter(Boolean).join("\n");
	}
	throw new Error(`No overlay source for harness ${name}`);
}

export function renderOverlay(resolved: ResolvedHarness, root?: string, includeCommon = true): string {
	return `<harness>
${overlayBody(resolved.name, root, includeCommon)}
</harness>`;
}

